import type { Meta, StoryObj } from '@storybook/react-vite';
import { useState } from 'react';
import { expect, within } from 'storybook/test';
import { Input } from '../ui/Input';
import { iconCatalog } from './catalog';
import { AngleDownIcon, CloseIcon, InfoCircleIcon } from './figma';

// Every icon on the Figma Icons page, generated by build-icons.mjs. Import by Figma name in PascalCase:
// Figma "angle-down" → `import { AngleDownIcon } from '../icons'`.
function IconGallery() {
  const [query, setQuery] = useState('');
  const q = query.trim().toLowerCase();
  const shown = iconCatalog.filter((i) => !q || i.name.includes(q) || i.group.toLowerCase().includes(q));
  const groups = [...new Set(shown.map((i) => i.group))];
  return (
    <div className="flex flex-col gap-6">
      <div className="flex flex-wrap items-center justify-between gap-4">
        <p className="text-sm text-body">
          {iconCatalog.length} icons from the Figma Icons page. Each is a 1em square that follows the text colour; size it with a
          class such as <code>size-5</code>.
        </p>
        <Input
          type="search"
          size="sm"
          className="w-64"
          placeholder="Search icons"
          aria-label="Search icons"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
        />
      </div>
      {groups.length === 0 && <p className="text-sm text-body">No icon matches “{query}”.</p>}
      {groups.map((group) => (
        <section key={group} className="flex flex-col gap-3" aria-label={group}>
          <h2 className="text-base font-semibold text-heading">{group}</h2>
          <ul className="grid grid-cols-2 gap-2 sm:grid-cols-4 lg:grid-cols-6">
            {shown.filter((i) => i.group === group).map(({ name, component, Icon }) => (
              <li key={name} className="flex flex-col items-center gap-2 rounded-base border border-default p-3 text-center" title={component}>
                <Icon className="size-6 text-heading" />
                <span className="text-xs leading-4 text-body">{name}</span>
              </li>
            ))}
          </ul>
        </section>
      ))}
    </div>
  );
}

const meta = {
  title: 'Foundations/Icons',
  component: IconGallery,
  parameters: { layout: 'padded' },
} satisfies Meta<typeof IconGallery>;

export default meta;
type Story = StoryObj<typeof meta>;

export const Gallery: Story = {};

// Search narrows the gallery by icon name or group.
export const Search: Story = {
  play: async ({ canvas, userEvent }) => {
    await userEvent.type(canvas.getByRole('searchbox', { name: 'Search icons' }), 'angle');
    const arrows = canvas.getByRole('region', { name: 'Arrows' });
    await expect(within(arrows).getAllByRole('listitem')).toHaveLength(4);
    await userEvent.clear(canvas.getByRole('searchbox', { name: 'Search icons' }));
    await userEvent.type(canvas.getByRole('searchbox', { name: 'Search icons' }), 'zzz');
    await expect(canvas.getByText('No icon matches “zzz”.')).toBeVisible();
  },
};

// Icons follow the text colour and size of their context; a `title` gives an icon an accessible name.
export const ColourSizeAndName: Story = {
  render: () => (
    <div className="flex items-center gap-4">
      <AngleDownIcon className="size-4 text-body" />
      <InfoCircleIcon className="size-6 text-fg-brand" />
      <CloseIcon className="size-8 text-fg-danger" title="Close" />
    </div>
  ),
  play: async ({ canvas }) => {
    await expect(canvas.getByRole('img', { name: 'Close' })).toBeVisible();
    await expect(canvas.queryAllByRole('img')).toHaveLength(1);
  },
};
